","required":true},{"id":"evidence","label":"Тип свидетельства","section":"","type":"enum","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#evidenceStatus","target":"article","description":"Тип свидетельства","required":true,"options":["synthetic","attested"]},{"id":"comment","label":"Комментарий исследователя","section":"","type":"richText","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#researcherAnnotation","target":"article","description":"Комментарий исследователя"},{"id":"url","label":"URL источника","section":"","type":"reference","predicate":"http://purl.org/dc/terms/source","target":"article","description":"URL источника"},{"id":"episode","label":"Эпизод / серия","section":"","type":"text","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#episodeTitle","target":"article","description":"Эпизод / серия"},{"id":"speaker","label":"Говорящий","section":"","type":"text","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#speaker","target":"article","description":"Говорящий"},{"id":"start","label":"Начало, секунды","section":"","type":"number","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#startSeconds","target":"article","description":"Начало, секунды"},{"id":"end","label":"Конец, секунды","section":"","type":"number","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#endSeconds","target":"article","description":"Конец, секунды"},{"id":"language","label":"Язык фрагмента","section":"","type":"enum","predicate":"http://purl.org/dc/terms/language","target":"article","description":"Язык фрагмента","options":["ru","en"]},{"id":"transcriptProvenance","label":"Происхождение транскрипта","section":"","type":"text","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#transcriptProvenance","target":"article","description":"Происхождение транскрипта"}]},{"id":"related","label":"Связанные понятия","section":"Связанные термины","type":"reference","predicate":"http://www.w3.org/2004/02/skos/core#related","target":"concept","description":"Связанные понятия","multiple":true},{"id":"sources","label":"Источники","section":"Источники","type":"object","predicate":"http://purl.org/dc/terms/source","target":"article","description":"Источники","multiple":true,"fields":[{"id":"id","label":"Идентификатор источника","section":"","type":"text","predicate":"http://purl.org/dc/terms/identifier","target":"article","description":"Идентификатор источника","required":true},{"id":"title","label":"Название","section":"","type":"text","predicate":"http://purl.org/dc/terms/title","target":"article","description":"Название","required":true},{"id":"url","label":"Ссылка","section":"","type":"reference","predicate":"http://www.w3.org/2000/01/rdf-schema#seeAlso","target":"article","description":"Ссылка","required":true},{"id":"note","label":"Примечание / атрибуция","section":"","type":"text","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#sourceNote","target":"article","description":"Примечание / атрибуция"},{"id":"license","label":"Лицензия, если известна","section":"","type":"text","predicate":"http://purl.org/dc/terms/license","target":"article","description":"Лицензия, если известна"}]},{"id":"externalMappings","label":"Внешние соответствия","section":"Внешние соответствия","type":"object","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#externalMapping","target":"article","description":"Внешние соответствия","multiple":true,"fields":[{"id":"url","label":"Внешний идентификатор","section":"","type":"reference","predicate":"http://www.w3.org/2000/01/rdf-schema#seeAlso","target":"article","description":"Внешний идентификатор","required":true},{"id":"relation","label":"Тип соответствия","section":"","type":"enum","predicate":"https://neurolex-preview.sanocks.workers.dev/vocabulary#mappingRelation","target":"article","description":"Тип соответствия","required":true,"options":["exactMatch","closeMatch","relatedMatch"]}]}]}','sample-import','2026-10-09T00:00:00.000Z');
INSERT OR IGNORE INTO articles(id,body) VALUES('brain-computer-interface','{"id":"brain-computer-interface","revision":1,"current":{"id":"brain-computer-interface","schemaVersion":1,"values":{"term":"brain–computer interface","equivalent":"интерфейс мозг–компьютер","abbreviation":"BCI","category":"Интерфейсы","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Система коммуникации или управления, которая преобразует сигналы активности мозга в команды внешнему устройству, предоставляя канал взаимодействия, не зависящий от мышечного управления."}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Английский многокомпонентный термин объединяет brain и computer как участников взаимодействия. Русский эквивалент сохраняет эту структуру. Аббревиатура BCI обозначает полное выражение, а не отдельный концепт. В популярном объяснении термин может сближаться с метафорой «чтения мыслей»: такое употребление требует анализа контекста и не должно автоматически становиться новым значением термина."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Представьте, что сигнал мозга становится командой для курсора — это и есть интерфейс мозг–компьютер."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Объяснительная парафраза через конкретный сценарий управления. Пример создан для демонстрации интерфейса; это не цитата из подкаста."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"Wolpaw et al. · Brain-computer interfaces for communication and control (2002)","url":"https://pubmed.ncbi.nlm.nih.gov/12048038/","note":"Определение выше — редакторский пересказ, не дословная цитата."},{"id":"source-2","title":"Wolpaw, Millán & Ramsey · Definitions and principles (2020)","url":"https://pubmed.ncbi.nlm.nih.gov/32164849/","note":"Дополнительный материал о принципах BCI."}],"related":["electroencephalography","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"published":{"id":"brain-computer-interface","schemaVersion":1,"values":{"term":"brain–computer interface","equivalent":"интерфейс мозг–компьютер","abbreviation":"BCI","category":"Интерфейсы","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Система коммуникации или управления, которая преобразует сигналы активности мозга в команды внешнему устройству, предоставляя канал взаимодействия, не зависящий от мышечного управления."}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Английский многокомпонентный термин объединяет brain и computer как участников взаимодействия. Русский эквивалент сохраняет эту структуру. Аббревиатура BCI обозначает полное выражение, а не отдельный концепт. В популярном объяснении термин может сближаться с метафорой «чтения мыслей»: такое употребление требует анализа контекста и не должно автоматически становиться новым значением термина."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Представьте, что сигнал мозга становится командой для курсора — это и есть интерфейс мозг–компьютер."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Объяснительная парафраза через конкретный сценарий управления. Пример создан для демонстрации интерфейса; это не цитата из подкаста."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"Wolpaw et al. · Brain-computer interfaces for communication and control (2002)","url":"https://pubmed.ncbi.nlm.nih.gov/12048038/","note":"Определение выше — редакторский пересказ, не дословная цитата."},{"id":"source-2","title":"Wolpaw, Millán & Ramsey · Definitions and principles (2020)","url":"https://pubmed.ncbi.nlm.nih.gov/32164849/","note":"Дополнительный материал о принципах BCI."}],"related":["electroencephalography","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"publishedRevision":1,"updatedAt":"2026-10-09T00:00:00.000Z"}');
INSERT OR IGNORE INTO revisions(article_id,revision,body) VALUES('brain-computer-interface',1,'{"revision":1,"document":{"id":"brain-computer-interface","schemaVersion":1,"values":{"term":"brain–computer interface","equivalent":"интерфейс мозг–компьютер","abbreviation":"BCI","category":"Интерфейсы","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Система коммуникации или управления, которая преобразует сигналы активности мозга в команды внешнему устройству, предоставляя канал взаимодействия, не зависящий от мышечного управления."}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Английский многокомпонентный термин объединяет brain и computer как участников взаимодействия. Русский эквивалент сохраняет эту структуру. Аббревиатура BCI обозначает полное выражение, а не отдельный концепт. В популярном объяснении термин может сближаться с метафорой «чтения мыслей»: такое употребление требует анализа контекста и не должно автоматически становиться новым значением термина."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Представьте, что сигнал мозга становится командой для курсора — это и есть интерфейс мозг–компьютер."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Объяснительная парафраза через конкретный сценарий управления. Пример создан для демонстрации интерфейса; это не цитата из подкаста."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"Wolpaw et al. · Brain-computer interfaces for communication and control (2002)","url":"https://pubmed.ncbi.nlm.nih.gov/12048038/","note":"Определение выше — редакторский пересказ, не дословная цитата."},{"id":"source-2","title":"Wolpaw, Millán & Ramsey · Definitions and principles (2020)","url":"https://pubmed.ncbi.nlm.nih.gov/32164849/","note":"Дополнительный материал о принципах BCI."}],"related":["electroencephalography","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"actor":"sample-import","origin":"import","time":"2026-10-09T00:00:00.000Z","action":"seed-sample"}');
INSERT OR IGNORE INTO articles(id,body) VALUES('electroencephalography','{"id":"electroencephalography","revision":1,"current":{"id":"electroencephalography","schemaVersion":1,"values":{"term":"electroencephalography","equivalent":"электроэнцефалография","abbreviation":"EEG","category":"Методы регистрации","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод регистрации электрической активности мозга с помощью электродов, размещённых на коже головы."}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В статье различаются метод — electroencephalography — и результат регистрации — electroencephalogram. В англоязычном дискурсе сокращение EEG может обозначать и метод, и запись: интерпретацию следует устанавливать по контексту. Русское ЭЭГ также требует контекстного уточнения. Применение EEG в BCI не делает эти термины синонимами: первый обозначает способ регистрации, второй — систему взаимодействия."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы записали EEG, а затем посмотрели, как менялся сигнал во время задания."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический пример: «EEG» здесь обозначает запись. Серия, говорящий и таймкод отсутствуют, поскольку источник не засвидетельствован."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NINDS · Neurological Diagnostic Tests and Procedures","url":"https://www.ninds.nih.gov/health-information/disorders/neurological-diagnostic-tests-and-procedures","note":"Редакторский пересказ раздела Electroencephalography."}],"related":["brain-computer-interface","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"published":{"id":"electroencephalography","schemaVersion":1,"values":{"term":"electroencephalography","equivalent":"электроэнцефалография","abbreviation":"EEG","category":"Методы регистрации","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод регистрации электрической активности мозга с помощью электродов, размещённых на коже головы."}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В статье различаются метод — electroencephalography — и результат регистрации — electroencephalogram. В англоязычном дискурсе сокращение EEG может обозначать и метод, и запись: интерпретацию следует устанавливать по контексту. Русское ЭЭГ также требует контекстного уточнения. Применение EEG в BCI не делает эти термины синонимами: первый обозначает способ регистрации, второй — систему взаимодействия."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы записали EEG, а затем посмотрели, как менялся сигнал во время задания."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический пример: «EEG» здесь обозначает запись. Серия, говорящий и таймкод отсутствуют, поскольку источник не засвидетельствован."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NINDS · Neurological Diagnostic Tests and Procedures","url":"https://www.ninds.nih.gov/health-information/disorders/neurological-diagnostic-tests-and-procedures","note":"Редакторский пересказ раздела Electroencephalography."}],"related":["brain-computer-interface","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"publishedRevision":1,"updatedAt":"2026-10-09T00:00:00.000Z"}');
INSERT OR IGNORE INTO revisions(article_id,revision,body) VALUES('electroencephalography',1,'{"revision":1,"document":{"id":"electroencephalography","schemaVersion":1,"values":{"term":"electroencephalography","equivalent":"электроэнцефалография","abbreviation":"EEG","category":"Методы регистрации","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод регистрации электрической активности мозга с помощью электродов, размещённых на коже головы."}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В статье различаются метод — electroencephalography — и результат регистрации — electroencephalogram. В англоязычном дискурсе сокращение EEG может обозначать и метод, и запись: интерпретацию следует устанавливать по контексту. Русское ЭЭГ также требует контекстного уточнения. Применение EEG в BCI не делает эти термины синонимами: первый обозначает способ регистрации, второй — систему взаимодействия."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы записали EEG, а затем посмотрели, как менялся сигнал во время задания."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический пример: «EEG» здесь обозначает запись. Серия, говорящий и таймкод отсутствуют, поскольку источник не засвидетельствован."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NINDS · Neurological Diagnostic Tests and Procedures","url":"https://www.ninds.nih.gov/health-information/disorders/neurological-diagnostic-tests-and-procedures","note":"Редакторский пересказ раздела Electroencephalography."}],"related":["brain-computer-interface","neurofeedback"],"externalMappings":[],"sampleRecord":true}},"actor":"sample-import","origin":"import","time":"2026-10-09T00:00:00.000Z","action":"seed-sample"}');
INSERT OR IGNORE INTO articles(id,body) VALUES('neurofeedback','{"id":"neurofeedback","revision":1,"current":{"id":"neurofeedback","schemaVersion":1,"values":{"term":"neurofeedback","equivalent":"нейрообратная связь","abbreviation":"","category":"Практики саморегуляции","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод обучения саморегуляции мозговой активности через обратную связь, предоставляемую человеку на основе измеряемых сигналов."}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сложное слово neurofeedback сочетает указание на нейронную активность с понятием обратной связи. В русскоязычных материалах встречаются как калька, так и заимствование. EEG-based neurofeedback обозначает частный случай: не вся нейрообратная связь основана на EEG. Различайте описание метода, обещание эффекта и исследовательскую интерпретацию."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"На экране меняется индикатор, а участник пробует научиться влиять на него, наблюдая обратную связь."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический учебный пример объяснения через интерфейс. Это не доказательство эффективности метода и не реальный подкастовый фрагмент."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NLM MeSH · Neurofeedback","url":"https://www.ncbi.nlm.nih.gov/mesh/D058765","note":"Редакторский пересказ определения контролируемого словаря."},{"id":"source-2","title":"Sitaram et al. · Closed-loop brain training: the science of neurofeedback","url":"https://www.nature.com/articles/nrn.2016.164","note":"Обзор разных методов регистрации и принципов обратной связи."}],"related":["electroencephalography","brain-computer-interface"],"externalMappings":[],"sampleRecord":true}},"published":{"id":"neurofeedback","schemaVersion":1,"values":{"term":"neurofeedback","equivalent":"нейрообратная связь","abbreviation":"","category":"Практики саморегуляции","definition":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Метод обучения саморегуляции мозговой активности через обратную связь, предоставляемую человеку на основе измеряемых сигналов."}]}]},"analysis":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сложное слово neurofeedback сочетает указание на нейронную активность с понятием обратной связи. В русскоязычных материалах встречаются как калька, так и заимствование. EEG-based neurofeedback обозначает частный случай: не вся нейрообратная связь основана на EEG. Различайте описание метода, обещание эффекта и исследовательскую интерпретацию."}]}]},"examples":[{"excerpt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"На экране меняется индикатор, а участник пробует научиться влиять на него, наблюдая обратную связь."}]}]},"evidence":"synthetic","comment":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Синтетический учебный пример объяснения через интерфейс. Это не доказательство эффективности метода и не реальный подкастовый фрагмент."}]}]},"language":"ru"}],"sources":[{"id":"source-1","title":"NLM MeSH · Neurofeedback","url":"https://www.ncbi.nlm.nih.gov/mesh/D058765","note":"Редакторский пересказ определения контролируемого словаря."},{"id":"source-2","title":"Sitaram et al. · Closed-loop brain training: the science of neurofeedback","url":"https://www.nature.com/articles/nrn.2016.164","note":"Обзор разных методов регистрации и принципов обратной связи."}],"related":["electroencephalography","brain-computer-interface"],"externalMappings":[],"sampleRecord":true}},"publishedRevision":1,"updatedAt":"2026-10-09T00:00:00.000Z"}');
